// Recipe data structure types based on recipes.json

export interface Recipe {
  id: number
  title: string
  ingredients: string[]
  how_to_cook: string[]
  image_path: string
}

export interface Category {
  id: string
  name_en: string
  name_uk: string
  start_marker: string
  end_marker: string | null
  recipes: Recipe[]
}

export interface RecipeData {
  categories: Category[]
}

// Page types for the recipe book
export type PageType = 'intro' | 'recipe' | 'section-divider'

export interface IntroPageData {
  type: 'intro'
}

export interface RecipePageData {
  type: 'recipe'
  recipe: Recipe
  categoryId: string
  categoryNameUk: string
}

export interface SectionDividerPageData {
  type: 'section-divider'
  categoryName: string
  categoryId: string
}

export type Page = IntroPageData | RecipePageData | SectionDividerPageData

import type { RecipeData } from '@/types/recipe'
import recipesData from '@/public/recipes.json'

/**
 * Loads and validates recipe data from recipes.json
 * @returns Typed recipe data with all categories and recipes
 * @throws Error if data is malformed or missing required fields
 */
export function loadRecipes(): RecipeData {
  try {
    // Validate that we have the expected structure
    if (!recipesData || !recipesData.categories || !Array.isArray(recipesData.categories)) {
      throw new Error('Invalid recipes.json structure: missing categories array')
    }

    // Validate each category
    recipesData.categories.forEach((category, index) => {
      if (!category.id || !category.name_uk || !Array.isArray(category.recipes)) {
        throw new Error(`Invalid category at index ${index}: missing required fields`)
      }
    })

    return recipesData as RecipeData
  } catch (error) {
    console.error('Error loading recipes:', error)
    throw error
  }
}

/**
 * Normalizes image paths from recipes.json format to Next.js public format
 * Converts "public/recipe_images/breakfast_1.jpeg" to "/recipe_images/breakfast_1.jpeg"
 * @param imagePath - The image path from recipes.json
 * @returns Normalized path for Next.js Image component
 */
export function normalizeImagePath(imagePath: string): string {
  if (!imagePath) return '/placeholder.svg'

  // Remove 'public/' prefix if present
  if (imagePath.startsWith('public/')) {
    return '/' + imagePath.substring(7)
  }

  // If already starts with '/', return as is
  if (imagePath.startsWith('/')) {
    return imagePath
  }

  // Otherwise add '/' prefix
  return '/' + imagePath
}

import type { Page, RecipeData } from '@/types/recipe'
import { loadRecipes } from './recipe-loader'

/**
 * Builds the complete page array for the recipe book
 * Structure:
 * - 1 intro page
 * - 20 breakfast recipe pages
 * - 1 section divider ("Обід/вечеря")
 * - 25 lunch/dinner recipe pages
 * - 1 section divider ("Десерти")
 * - 20 dessert recipe pages
 * Total: ~67 pages
 *
 * @returns Array of Page objects in the correct order
 */
export function buildPageArray(): Page[] {
  const recipeData = loadRecipes()
  const pages: Page[] = []

  // Add intro page as the first page
  pages.push({
    type: 'intro'
  })

  // Process each category in order
  recipeData.categories.forEach((category, categoryIndex) => {
    // Add section divider before lunch/dinner and desserts categories
    // (Skip divider for breakfast as it comes right after intro)
    if (categoryIndex > 0) {
      pages.push({
        type: 'section-divider',
        categoryName: category.name_uk,
        categoryId: category.id
      })
    }

    // Add all recipes from this category
    category.recipes.forEach((recipe) => {
      pages.push({
        type: 'recipe',
        recipe: recipe,
        categoryId: category.id,
        categoryNameUk: category.name_uk
      })
    })
  })

  return pages
}

/**
 * Gets statistics about the page array
 * Useful for validation and debugging
 */
export function getPageStats(pages: Page[]): {
  totalPages: number
  introPages: number
  recipePages: number
  dividerPages: number
  breakfastRecipes: number
  lunchDinnerRecipes: number
  dessertRecipes: number
} {
  const stats = {
    totalPages: pages.length,
    introPages: 0,
    recipePages: 0,
    dividerPages: 0,
    breakfastRecipes: 0,
    lunchDinnerRecipes: 0,
    dessertRecipes: 0
  }

  pages.forEach(page => {
    switch (page.type) {
      case 'intro':
        stats.introPages++
        break
      case 'recipe':
        stats.recipePages++
        if (page.categoryId === 'breakfast') stats.breakfastRecipes++
        else if (page.categoryId === 'lunch_dinner') stats.lunchDinnerRecipes++
        else if (page.categoryId === 'desserts') stats.dessertRecipes++
        break
      case 'section-divider':
        stats.dividerPages++
        break
    }
  })

  return stats
}

interface SectionDividerProps {
  categoryName: string
  categoryId: string
}

export function SectionDivider({ categoryName, categoryId }: SectionDividerProps) {
  // Map category IDs to decorative elements
  const getDecorativeElement = () => {
    switch (categoryId) {
      case 'lunch_dinner':
        return '🍽️'
      case 'desserts':
        return '🍰'
      default:
        return '✨'
    }
  }

  return (
    <div className="min-h-screen flex flex-col justify-center items-center px-8 py-16 bg-gradient-to-br from-background via-muted/30 to-background">
      <div className="max-w-4xl mx-auto text-center">
        <div className="mb-12">
          <div className="text-6xl mb-8 opacity-40">
            {getDecorativeElement()}
          </div>
        </div>

        <div className="mb-12">
          <div className="recipe-divider w-24 mx-auto mb-12 rotate-180"></div>

          <h2 className="text-7xl md:text-8xl font-serif text-foreground mb-8 text-balance leading-tight">
            {categoryName}
          </h2>

          <div className="recipe-divider w-24 mx-auto"></div>
        </div>

        <div className="mt-16">
          <p className="text-sm text-muted-foreground italic tracking-wide">
            Гортайте далі для перегляду рецептів
          </p>
        </div>
      </div>
    </div>
  )
}

import { memo } from 'react'
import Image from 'next/image'
